class UserRepositoryTest {
    private lateinit var db: AppDatabase
    private lateinit var server: MockWebServer
    private lateinit var repo: UserRepository

    @Before fun setUp() {
        db = Room.inMemoryDatabaseBuilder(context, AppDatabase::class.java)
            .allowMainThreadQueries()
            .build()
        server = MockWebServer().apply { start() }
        repo = UserRepository(api = retrofitTo(server.url("/")), dao = db.userDao(), io = UnconfinedTestDispatcher())
    }

    @After fun tearDown() { db.close(); server.shutdown() }

    @Test
    fun `refresh writes through to the database`() = runTest {
        server.enqueue(MockResponse().setBody("""{"id":"1","name":"Ada"}"""))

        repo.refresh("1")

        assertEquals("Ada", db.userDao().find("1")?.name)
    }
}

class FakeUserRepository : UserRepository {
    private val users = MutableStateFlow(emptyList<User>())
    override fun observe() = users
    override suspend fun save(u: User) { users.update { it + u } }
    fun emit(list: List<User>) { users.value = list }   // test control surface
}
